<?php require 'config.php'; $msg='';
if($_SERVER['REQUEST_METHOD']=='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$pass=$_POST['password'];
$s=$conn->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$hash=password_hash($pass,PASSWORD_DEFAULT);$s->bind_param("sss",$name,$email,$hash);
if($s->execute()) header("Location: login.php"); else $msg="อีเมลนี้ถูกใช้งานแล้ว"; }
